-- 2. RLS Policies from Production
ALTER TABLE public."chart_of_accounts" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admin can manage chart_of_accounts" ON public."chart_of_accounts";
CREATE POLICY "Admin can manage chart_of_accounts" ON public."chart_of_accounts" FOR ALL TO authenticated USING ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text]))) WITH CHECK ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text])));
ALTER TABLE public."chart_of_accounts" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Authenticated can read chart_of_accounts" ON public."chart_of_accounts";
CREATE POLICY "Authenticated can read chart_of_accounts" ON public."chart_of_accounts" FOR SELECT TO authenticated USING (true);
ALTER TABLE public."fms_audit_log" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admin can read fms_audit_log" ON public."fms_audit_log";
CREATE POLICY "Admin can read fms_audit_log" ON public."fms_audit_log" FOR SELECT TO authenticated USING ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text])));
ALTER TABLE public."fms_budgets" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admin can manage fms_budgets" ON public."fms_budgets";
CREATE POLICY "Admin can manage fms_budgets" ON public."fms_budgets" FOR ALL TO authenticated USING ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text]))) WITH CHECK ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text])));
ALTER TABLE public."fms_budgets" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Staff can read fms_budgets" ON public."fms_budgets";
CREATE POLICY "Staff can read fms_budgets" ON public."fms_budgets" FOR SELECT TO authenticated USING (true);
ALTER TABLE public."fms_transactions" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admin can manage fms_transactions" ON public."fms_transactions";
CREATE POLICY "Admin can manage fms_transactions" ON public."fms_transactions" FOR ALL TO authenticated USING ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text]))) WITH CHECK ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text])));
ALTER TABLE public."fms_transactions" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users can read own zone fms_transactions" ON public."fms_transactions";
CREATE POLICY "Users can read own zone fms_transactions" ON public."fms_transactions" FOR SELECT TO authenticated USING (((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text])) OR ((zone_code)::text = (( SELECT profiles.zone_code
   FROM profiles
  WHERE (profiles.id = auth.uid())))::text)));
ALTER TABLE public."party_files" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Authenticated can manage files" ON public."party_files";
CREATE POLICY "Authenticated can manage files" ON public."party_files" FOR ALL TO public USING ((auth.uid() IS NOT NULL)) WITH CHECK ((auth.uid() IS NOT NULL));
ALTER TABLE public."party_folders" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Authenticated can manage folders" ON public."party_folders";
CREATE POLICY "Authenticated can manage folders" ON public."party_folders" FOR ALL TO public USING ((auth.uid() IS NOT NULL)) WITH CHECK ((auth.uid() IS NOT NULL));
ALTER TABLE public."profiles" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Super admin and admin can update profiles" ON public."profiles";
CREATE POLICY "Super admin and admin can update profiles" ON public."profiles" FOR UPDATE TO public USING ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text])));
ALTER TABLE public."profiles" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Super admin and admin can view all profiles" ON public."profiles";
CREATE POLICY "Super admin and admin can view all profiles" ON public."profiles" FOR SELECT TO public USING ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text])));
ALTER TABLE public."records" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admin can manage all records" ON public."records";
CREATE POLICY "Admin can manage all records" ON public."records" FOR ALL TO public USING ((get_user_role() = 'admin'::text));
ALTER TABLE public."records" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Commune chief can manage commune records" ON public."records";
CREATE POLICY "Commune chief can manage commune records" ON public."records" FOR ALL TO public USING (((get_user_role() = 'commune_chief'::text) AND (commune_id = get_user_commune())));
ALTER TABLE public."records" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Commune clerk can manage commune records" ON public."records";
CREATE POLICY "Commune clerk can manage commune records" ON public."records" FOR ALL TO public USING (((get_user_role() = 'commune_clerk'::text) AND (commune_id = get_user_commune())));
ALTER TABLE public."records" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Commune clerk can view commune records" ON public."records";
CREATE POLICY "Commune clerk can view commune records" ON public."records" FOR SELECT TO public USING (((get_user_role() = 'commune_clerk'::text) AND (commune_id = get_user_commune())));
ALTER TABLE public."records" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "District chief can view records in district" ON public."records";
CREATE POLICY "District chief can view records in district" ON public."records" FOR SELECT TO public USING (((get_user_role() = 'district_chief'::text) AND (commune_id IN ( SELECT communes.id
   FROM communes
  WHERE (communes.district_id IN ( SELECT communes_1.district_id
           FROM communes communes_1
          WHERE (communes_1.id = get_user_commune())))))));
ALTER TABLE public."records" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Recorder can create records" ON public."records";
CREATE POLICY "Recorder can create records" ON public."records" FOR INSERT TO public WITH CHECK ((get_user_role() = 'recorder'::text));
ALTER TABLE public."records" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Super admin can do everything" ON public."records";
CREATE POLICY "Super admin can do everything" ON public."records" FOR ALL TO public USING ((get_user_role() = 'super_admin'::text));
ALTER TABLE public."records" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Village chief can manage village records" ON public."records";
CREATE POLICY "Village chief can manage village records" ON public."records" FOR ALL TO public USING (((get_user_role() = 'village_chief'::text) AND (village_id = get_user_village())));
ALTER TABLE public."report_documents" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Staff can manage report documents" ON public."report_documents";
CREATE POLICY "Staff can manage report documents" ON public."report_documents" FOR ALL TO public USING ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text, 'district_chief'::text, 'commune_chief'::text, 'commune_clerk'::text, 'village_chief'::text, 'recorder'::text])));
ALTER TABLE public."report_template_keys" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "template_keys_delete" ON public."report_template_keys";
CREATE POLICY "template_keys_delete" ON public."report_template_keys" FOR DELETE TO authenticated USING ((auth.uid() IS NOT NULL));
ALTER TABLE public."report_template_keys" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "template_keys_insert" ON public."report_template_keys";
CREATE POLICY "template_keys_insert" ON public."report_template_keys" FOR INSERT TO authenticated WITH CHECK ((auth.uid() IS NOT NULL));
ALTER TABLE public."report_template_keys" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "template_keys_select" ON public."report_template_keys";
CREATE POLICY "template_keys_select" ON public."report_template_keys" FOR SELECT TO authenticated USING (true);
ALTER TABLE public."report_template_keys" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "template_keys_update" ON public."report_template_keys";
CREATE POLICY "template_keys_update" ON public."report_template_keys" FOR UPDATE TO authenticated USING ((auth.uid() IS NOT NULL));
ALTER TABLE public."report_templates" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admin can manage report templates" ON public."report_templates";
CREATE POLICY "Admin can manage report templates" ON public."report_templates" FOR ALL TO public USING ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text])));
ALTER TABLE public."report_templates" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Staff can read report templates" ON public."report_templates";
CREATE POLICY "Staff can read report templates" ON public."report_templates" FOR SELECT TO public USING ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text, 'district_chief'::text, 'commune_chief'::text, 'commune_clerk'::text, 'village_chief'::text, 'recorder'::text])));
ALTER TABLE public."role_permissions" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admin can update role_permissions" ON public."role_permissions";
CREATE POLICY "Admin can update role_permissions" ON public."role_permissions" FOR ALL TO public USING ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text])));
ALTER TABLE public."role_permissions" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Anyone authenticated can read role_permissions" ON public."role_permissions";
CREATE POLICY "Anyone authenticated can read role_permissions" ON public."role_permissions" FOR SELECT TO public USING ((auth.uid() IS NOT NULL));
ALTER TABLE public."roles" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admin can manage roles" ON public."roles";
CREATE POLICY "Admin can manage roles" ON public."roles" FOR ALL TO authenticated USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['super_admin'::text, 'admin'::text])))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['super_admin'::text, 'admin'::text]))))));
ALTER TABLE public."roles" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Anyone authenticated can read roles" ON public."roles";
CREATE POLICY "Anyone authenticated can read roles" ON public."roles" FOR SELECT TO authenticated USING (true);
