CREATE POLICY "Allow admin full access to system settings" ON public."system_settings" FOR ALL TO public USING ((((auth.jwt() ->> 'role'::text) = 'admin'::text) OR (auth.role() = 'service_role'::text)));
ALTER TABLE public."system_settings" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public read access to non-secret system settings" ON public."system_settings";
CREATE POLICY "Allow public read access to non-secret system settings" ON public."system_settings" FOR SELECT TO public USING (true);
ALTER TABLE public."user_roles" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admin can manage user_roles" ON public."user_roles";
CREATE POLICY "Admin can manage user_roles" ON public."user_roles" FOR ALL TO public USING ((get_user_role() = ANY (ARRAY['super_admin'::text, 'admin'::text])));
ALTER TABLE public."user_roles" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users can view own roles" ON public."user_roles";
CREATE POLICY "Users can view own roles" ON public."user_roles" FOR SELECT TO public USING ((auth.uid() = user_id));
ALTER TABLE public."zone_chief_assignments" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admin can manage zone_chief_assignments" ON public."zone_chief_assignments";
CREATE POLICY "Admin can manage zone_chief_assignments" ON public."zone_chief_assignments" FOR ALL TO authenticated USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['super_admin'::text, 'admin'::text])))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['super_admin'::text, 'admin'::text]))))));
ALTER TABLE public."zone_chief_assignments" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Anyone authenticated can read zone_chief_assignments" ON public."zone_chief_assignments";
CREATE POLICY "Anyone authenticated can read zone_chief_assignments" ON public."zone_chief_assignments" FOR SELECT TO authenticated USING (true);